476	fn normalize_comment<'a>(
477	    comment: &'a SourceComment,
478	    source: SourceCode<'a>,
479	) -> FormatResult<Cow<'a, str>> {
480	    let slice = comment.slice();
481	    let comment_text = slice.text(source);
482	
483	    let trimmed = comment_text.trim_end();
484	
485	    let content = strip_comment_prefix(trimmed)?;
486	
487	    if content.is_empty() {
488	        return Ok(Cow::Borrowed("#"));
489	    }
490	
491	    // Fast path for correctly formatted comments: if the comment starts with a space, or any
492	    // of the allowed characters, then it's included verbatim (apart for trimming any trailing
493	    // whitespace).
494	    if content.starts_with([' ', '!', ':', '#', '\'']) {
495	        return Ok(Cow::Borrowed(trimmed));
496	    }
497	
498	    // Otherwise, we need to normalize the comment by adding a space after the `#`.
499	    if content.starts_with('\u{A0}') {
500	        let trimmed = content.trim_start_matches('\u{A0}');
501	        if trimmed.trim_start().starts_with("type:") {
502	            // Black adds a space before the non-breaking space if part of a type pragma.
503	            Ok(Cow::Owned(std::format!("# {content}")))
504	        } else if trimmed.starts_with(' ') {
505	            // Black replaces the non-breaking space with a space if followed by a space.
506	            Ok(Cow::Owned(std::format!("# {trimmed}")))
507	        } else {
508	            // Otherwise we replace the first non-breaking space with a regular space.
509	            Ok(Cow::Owned(std::format!("# {}", &content["\u{A0}".len()..])))
510	        }
511	    } else {
512	        Ok(Cow::Owned(std::format!("# {}", content.trim_start())))
513	    }
514	}
