516	/// A helper for stripping '#' from comments.
517	fn strip_comment_prefix(comment_text: &str) -> FormatResult<&str> {
518	    let Some(content) = comment_text.strip_prefix('#') else {
519	        return Err(FormatError::syntax_error(
520	            "Didn't find expected comment token `#`",
521	        ));
522	    };
523	
524	    Ok(content)
525	}
